import { useMemo, useState } from "react";
import axios from "axios";
import "../styles/AdminPage.css";
import { regionOptions } from "../data/cameroonDistricts";
import { supabase } from '../supabaseClient'
import { regionCoordinates } from "../regiocor";


const initialFormState = {
  date: "",
  region: "",
  district: "",
  suspected: "",
  confirmed: "",
  deaths: ""
};

function AdminPage() {
  const [formData, setFormData] = useState(initialFormState);
  const [loading, setLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");

  const cfr = useMemo(() => {
    const confirmed = Number(formData.confirmed) || 0;
    const deaths = Number(formData.deaths) || 0;

    if (confirmed === 0) {
      return 0;
    }

    return Number(((deaths / confirmed) * 100).toFixed(2));
  }, [formData.confirmed, formData.deaths]);

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((prev) => {
      if (name === "region") {
        return { ...prev, region: value, district: "" };
      }

      return { ...prev, [name]: value };
    });

    setSuccessMessage("");
    setErrorMessage("");
  };

  const today = new Date().toISOString().split("T")[0];

const fetchNasaData = async (lat, lon, date) => {
  const formattedDate = date.replace(/-/g, ""); // YYYYMMDD
  const url = `https://power.larc.nasa.gov/api/temporal/daily/point?parameters=PRECTOT,T2M,RH2M&community=RE&longitude=${lon}&latitude=${lat}&start=${formattedDate}&end=${formattedDate}&format=JSON`;

  const res = await fetch(url);
  const json = await res.json();

  const rainfall = json?.properties?.parameter?.PRECTOT?.[formattedDate] ?? null;
  const temperature = json?.properties?.parameter?.T2M?.[formattedDate] ?? null;
  const humidity = json?.properties?.parameter?.RH2M?.[formattedDate] ?? null;

  return { rainfall, temperature, humidity };
};


const handleSubmit = async (event) => {
  event.preventDefault();
  setLoading(true);
  setSuccessMessage("");
  setErrorMessage("");

  try {
    // Get lat/lon for the selected region
    const coords = regionCoordinates[formData.region];
    if (!coords) {
      throw new Error("Coordinates not found for selected region");
    }

    // Fetch NASA data
    const nasaData = await fetchNasaData(coords.lat, coords.lon, formData.date);

    // Build payload
    const payload = {
      date: formData.date,
      region: formData.region,
      district: formData.district,
      suspected: Number(formData.suspected) || 0,
      confirmed: Number(formData.confirmed) || 0,
      deaths: Number(formData.deaths) || 0,
      cfr,
      rainfall: nasaData.rainfall,
      temperature: nasaData.temperature,
      humidity: nasaData.humidity
    };

    // Insert into Supabase
    const { data, error } = await supabase
      .from("reports")
      .insert([payload])
      .select();

    if (error) throw error;

    console.log("Inserted row:", data);
    setSuccessMessage("Report submitted successfully.");
    setFormData(initialFormState);
  } catch (error) {
    console.error("Submission error:", error);
    setErrorMessage(error.message || "Submission failed.");
  } finally {
    setLoading(false);
  }
};


  return (
    <main className="admin-page">
      <section className="admin-card" aria-labelledby="admin-page-title">
        <h1 id="admin-page-title">Cholera Pandemic Case Data Entry - Cameroon</h1>
        <p className="admin-subtitle">
          Use this form to submit daily cholera district-level pandemic surveillance reports.
        </p>

        <form className="admin-form" onSubmit={handleSubmit}>
          <label htmlFor="date">Report Date</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            max={today}
            required
          />

          <label htmlFor="region">Region</label>
          <select
            id="region"
            name="region"
            value={formData.region}
            onChange={handleChange}
            required
          >
            <option value="">Select a region</option>
            {regionOptions.map((region) => (
              <option key={region} value={region}>
                {region}
              </option>
            ))}
          </select>

          <label htmlFor="district">District</label>
          <input
            id="district"
            name="district"
            type="text"
            placeholder="Enter district name"
            value={formData.district}
            onChange={handleChange}
            required
          />

          <label htmlFor="suspected">Suspected Cases</label>
          <input
            id="suspected"
            name="suspected"
            type="number"
            min="0"
            value={formData.suspected}
            onChange={handleChange}
            required
          />

          <label htmlFor="confirmed">Confirmed Cases</label>
          <input
            id="confirmed"
            name="confirmed"
            type="number"
            min="0"
            value={formData.confirmed}
            onChange={handleChange}
            required
          />

          <label htmlFor="deaths">Deaths</label>
          <input
            id="deaths"
            name="deaths"
            type="number"
            min="0"
            value={formData.deaths}
            onChange={handleChange}
            required
          />

          <label htmlFor="cfr">CFR (%)</label>
          <input id="cfr" name="cfr" type="text" value={cfr} readOnly />

          <button type="submit" disabled={loading}>
            {loading ? "Submitting..." : "Submit Data"}
          </button>
        </form>

        {successMessage && (
          <p className="status-message success" role="status">
            {successMessage}
          </p>
        )}

        {errorMessage && (
          <p className="status-message error" role="alert">
            {errorMessage}
          </p>
        )}
      </section>
    </main>
  );
}

export default AdminPage;
